package agentenv

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// File is one generated file.
type File struct {
	Path    string // repository-relative, slash-separated
	Content []byte
	Exec    bool
}

// Generate renders every file the spec's hosts need from the spec alone (it
// reads the existing JSON files only to keep their other keys). It never
// touches the network. The shape: one setup script every host runs, one check
// script that proves an environment, and, with services, one start script the
// hosts run per session (no host keeps processes from setup).
func Generate(root string, s Spec) ([]File, []string, error) {
	var notes []string
	fp := s.Fingerprint()
	files := []File{{Path: SpecPath, Content: s.Marshal()},
		{Path: SetupPath, Content: []byte(setupScript(s, fp)), Exec: true},
		{Path: CheckPath, Content: []byte(checkScript(s, fp)), Exec: true}}
	if len(s.Services) > 0 {
		files = append(files, File{Path: StartPath, Content: []byte(startScript(s, fp)), Exec: true})
	}
	if s.HasHost(Amp) && len(s.Services) > 0 {
		old, _ := os.ReadFile(filepath.Join(root, ResumePath))
		if len(old) > 0 && !bytes.Contains(old, []byte(GeneratedMarker)) {
			if !bytes.Contains(old, []byte(StartCommand)) {
				notes = append(notes, ResumePath+" is hand-written: add `"+StartCommand+"` to it so services start when an orb wakes")
			}
		} else {
			files = append(files, File{Path: ResumePath, Content: []byte(resumeScript(fp)), Exec: true})
		}
	}
	if s.HasHost(Cursor) {
		b, err := mergeJSON(root, CursorEnvPath, func(m map[string]any) {
			m["name"] = "aayudha (" + SetupPath + ")"
			m["install"] = SetupCommand
			if len(s.Services) > 0 {
				m["start"] = StartCommand
			} else if m["start"] == StartCommand {
				delete(m, "start")
			}
		})
		if err != nil {
			return nil, nil, err
		}
		files = append(files, File{Path: CursorEnvPath, Content: b})
	}
	if s.HasHost(Claude) {
		b, err := mergeJSON(root, ClaudeSetPath, func(m map[string]any) {
			hooks, _ := m["hooks"].(map[string]any)
			if hooks == nil {
				hooks = map[string]any{}
				m["hooks"] = hooks
			}
			list, _ := hooks["SessionStart"].([]any)
			var out []any
			for _, e := range list {
				if !isEnvHook(e) {
					out = append(out, e)
				}
			}
			hooks["SessionStart"] = append(out, map[string]any{"matcher": "startup|resume", "hooks": []any{
				map[string]any{"type": "command", "command": ClaudeHookCommand(len(s.Services) > 0), "timeout": json.Number("900")}}})
		})
		if err != nil {
			return nil, nil, err
		}
		files = append(files, File{Path: ClaudeSetPath, Content: b})
	}
	return files, notes, nil
}

// ClaudeHookCommand is the SessionStart hook that sets up a Claude Code cloud
// session: only where CLAUDE_CODE_REMOTE is true (never on a laptop), with
// setup's output in a log so it does not fill the session's context.
func ClaudeHookCommand(services bool) string {
	run := SetupCommand
	if services {
		run += " && " + StartCommand
	}
	return `if [ "${CLAUDE_CODE_REMOTE:-}" = true ]; then cd "$CLAUDE_PROJECT_DIR" && { ` + run + `; } > /tmp/aayu-env.log 2>&1 || { tail -n 40 /tmp/aayu-env.log >&2; exit 1; }; fi`
}

func isEnvHook(e any) bool {
	m, _ := e.(map[string]any)
	inner, _ := m["hooks"].([]any)
	for _, h := range inner {
		hm, _ := h.(map[string]any)
		if c, _ := hm["command"].(string); strings.Contains(c, "CLAUDE_CODE_REMOTE") && strings.Contains(c, SetupCommand) {
			return true
		}
	}
	return false
}

func mergeJSON(root, rel string, set func(map[string]any)) ([]byte, error) {
	old, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		return nil, err
	}
	m := map[string]any{}
	if len(bytes.TrimSpace(old)) > 0 {
		dec := json.NewDecoder(bytes.NewReader(old))
		dec.UseNumber()
		if err := dec.Decode(&m); err != nil {
			return nil, fmt.Errorf("%s: cannot merge into it (%w); fix the file first", rel, err)
		}
	}
	set(m)
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(m); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

func header(what, fp string) string {
	return "#!/usr/bin/env bash\n" + GeneratedMarker + " from " + SpecPath + " (environment " + fp + ").\n" +
		"# " + what + "\n# Change the spec and rerun `aayu install --env --apply`; do not edit this file.\n" +
		"set -euo pipefail\ncd \"$(dirname \"${BASH_SOURCE[0]}\")/..\"\n\n"
}

// prelude is shared by the scripts: root on Claude Code and Codex, a sudo user
// on Amp and Cursor; sudo resets PATH, so it keeps ours, plus the sbin
// directories a login shell of a non-root user lacks (service, for example).
const prelude = `step() { echo "==> [$(date +%H:%M:%S)] $*"; }
as_root() { if [ "$(id -u)" -eq 0 ]; then "$@"; else sudo -n env "PATH=/usr/local/sbin:/usr/sbin:/sbin:$PATH" "$@"; fi; }
version_ge() { [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | head -n1)" = "$2" ]; }
in_ranges() { # version "lo [hi]"...: half-open ranges
  local v=$1 r lo hi
  shift
  for r in "$@"; do
    lo=${r%% *}; hi=
    [ "$r" = "$lo" ] || hi=${r#* }
    if version_ge "$v" "$lo" && { [ -z "$hi" ] || ! version_ge "$v" "$hi"; }; then return 0; fi
  done
  return 1
}
`

func setupScript(s Spec, fp string) string {
	var b strings.Builder
	b.WriteString(header("The one setup script every agent host runs: Amp natively, Cursor (.cursor/environment.json install),\n# Codex cloud (Install script field), and Claude Code on the web (SessionStart hook in .claude/settings.json).\n# Idempotent and non-interactive; it leaves no process running (no host keeps them).", fp))
	b.WriteString(prelude)
	b.WriteString(`export DEBIAN_FRONTEND=noninteractive COREPACK_ENABLE_DOWNLOAD_PROMPT=0
case "$(uname -m)" in
  x86_64) ARCH=amd64 ;;
  aarch64 | arm64) ARCH=arm64 ;;
  *) echo "aayu-env: unsupported architecture $(uname -m)" >&2; exit 1 ;;
esac
apt_updated=
need_apt() { # installs only the missing packages, so a warm run makes no apt call
  local p missing=()
  for p in "$@"; do
    dpkg-query -W -f='${Status}' "$p" 2>/dev/null | grep -q "install ok installed" || missing+=("$p")
  done
  [ ${#missing[@]} -eq 0 ] && return 0
  step "apt: ${missing[*]}"
  if [ -z "$apt_updated" ]; then as_root apt-get update -qq; apt_updated=1; fi
  as_root apt-get install -y -qq --no-install-recommends "${missing[@]}"
}
fetch() { # url sha256 file: every download is checked against a pinned SHA-256
  curl -fsSL --retry 3 -o "$3" "$1"
  echo "$2  $3" | sha256sum -c --quiet -
}
path_first() { # a directory that must win in later shells too (Codex runs setup in its own shell)
  persist_line "export PATH=\"$1:\$PATH\""
  export PATH="$1:$PATH"
}
persist() { persist_line "export $1"; } # a variable later shells need
persist_line() { # Claude Code's Bash tool reads CLAUDE_ENV_FILE, not the shell profile
  local rc
  for rc in "$HOME/.bashrc" "$HOME/.profile" ${CLAUDE_ENV_FILE:+"$CLAUDE_ENV_FILE"}; do
    grep -qxF "$1" "$rc" 2>/dev/null || echo "$1" >> "$rc"
  done
}
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

`)
	pkgs := append([]string{"ca-certificates", "curl", "git", "xz-utils"}, s.Packages...)
	for _, sv := range s.Services {
		pkgs = append(pkgs, servicePackages[sv.Name]...)
	}
	fmt.Fprintf(&b, "step \"System packages\"\nneed_apt %s\n\n", strings.Join(dedupe(pkgs), " "))
	for _, t := range s.Tools {
		switch t.Name {
		case "go":
			writeGo(&b, t)
		case "node":
			writeNode(&b, t)
		case "uv":
			writeUV(&b, t)
		case "rust":
			writeRust(&b, t)
		}
	}
	if cp := s.Tool("corepack"); cp != nil {
		for _, pm := range []string{"pnpm", "yarn"} {
			if t := s.Tool(pm); t != nil {
				writeCorepack(&b, *cp, *t)
			}
		}
	}
	if s.EnvFile != "" {
		src, dst, _ := strings.Cut(s.EnvFile, " -> ")
		fmt.Fprintf(&b, "step \"%s from %s\"\n[ -f %s ] || cp -- %s %s\n", dst, src, dst, src, dst)
		// Agents' shells get its values, without overriding what the host sets.
		file := `"\"$PWD/` + dst + `\""`
		fmt.Fprintf(&b, "persist_line %s%s%s%s\n\n", shellQuote("[ -f "), file, shellQuote(" ] && "+dotenvLoop+" < "), file)
	}
	for _, sv := range s.Services {
		writeServiceSetup(&b, sv)
	}
	steps := func(title string, xs []Step) {
		for _, d := range xs {
			fmt.Fprintf(&b, "step %s # %s\n%s\n\n", shellQuote(title+": "+d.Run), d.Evidence, d.Run)
		}
	}
	steps("Dependencies", s.Deps)
	steps("Browsers", s.Browsers)
	steps("Step", s.Steps)
	if t := s.Tool("aayu"); t != nil {
		writeAayu(&b, *t)
	}
	b.WriteString(setupHook(s))
	b.WriteString("step \"Setup complete (environment " + fp + ")\"\n")
	return b.String()
}

// dotenvLoop, fed a dotenv file, exports each NAME=value not already set, in
// POSIX sh, so it also runs from ~/.profile.
const dotenvLoop = `while IFS='=' read -r k v || [ -n "$k" ]; do case "$k" in "" | [0-9]* | *[!A-Za-z0-9_]*) continue ;; esac; ` +
	`eval "[ -n \"\${$k:-}\" ]" || { v=${v%\"}; v=${v#\"}; export "$k=$v"; }; done`

// loadDotenv is the check's and start's copy of what setup persists.
func loadDotenv(s Spec) string {
	if s.EnvFile == "" {
		return ""
	}
	_, dst, _ := strings.Cut(s.EnvFile, " -> ")
	return "[ ! -f " + dst + " ] || " + dotenvLoop + " < " + dst + "\n"
}

func dedupe(xs []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, x := range xs {
		if !seen[x] {
			seen[x] = true
			out = append(out, x)
		}
	}
	return out
}

func archCase(t Tool, names map[string]string, indent string) string {
	var b strings.Builder
	b.WriteString("case \"$ARCH\" in\n")
	for _, a := range []string{"amd64", "arm64"} {
		fmt.Fprintf(&b, "%s  %s) sum=%s", indent, a, t.SHA256[a])
		if names != nil {
			fmt.Fprintf(&b, " name=%s", names[a])
		}
		b.WriteString(" ;;\n")
	}
	b.WriteString(indent + "esac\n" + indent)
	return b.String()
}

func writeGo(b *strings.Builder, t Tool) {
	fmt.Fprintf(b, `GO_VERSION=%s # %s
step "Go $GO_VERSION"
if [ "$(GOTOOLCHAIN=local /usr/local/go/bin/go env GOVERSION 2> /dev/null)" != "go$GO_VERSION" ]; then
  installed=
  # A Go already on the machine fetches the exact toolchain through the module proxy, checked against
  # the Go checksum database (proxy.golang.org is on every host's default allowlist; dl.google.com is not).
  if command -v go > /dev/null 2>&1 && goroot=$(GOTOOLCHAIN="go$GO_VERSION" GOFLAGS= go env GOROOT 2> /dev/null) &&
    [ "$(GOTOOLCHAIN=local "$goroot/bin/go" env GOVERSION 2> /dev/null)" = "go$GO_VERSION" ]; then
    as_root rm -rf /usr/local/go.aayu && as_root cp -a "$goroot" /usr/local/go.aayu
    as_root rm -rf /usr/local/go && as_root mv /usr/local/go.aayu /usr/local/go && as_root chmod -R u+w /usr/local/go
    installed=1
  fi
  if [ -z "$installed" ]; then
    %sfetch "https://dl.google.com/go/go$GO_VERSION.linux-$ARCH.tar.gz" "$sum" "$tmp/go.tar.gz"
    as_root rm -rf /usr/local/go
    as_root tar -C /usr/local -xzf "$tmp/go.tar.gz"
  fi
fi
as_root ln -sf /usr/local/go/bin/go /usr/local/go/bin/gofmt /usr/local/bin/
hash -r
# A GOROOT set for another Go (codex-universal's mise sets one) would make this go compile with that one's tools.
if [ -n "${GOROOT:-}" ] && [ "$GOROOT" != /usr/local/go ]; then persist GOROOT=/usr/local/go; export GOROOT=/usr/local/go; fi
[ "$(GOTOOLCHAIN=local go env GOVERSION)" = "go$GO_VERSION" ] || path_first /usr/local/go/bin
go version

`, t.Version, t.Evidence, archCase(t, nil, "    "))
}

// writeAayu puts aayu, and its alias, in ~/.local/bin (install.sh's default)
// for every later shell: loops and hooks call it (Bug #819). A warm run
// builds or downloads nothing when the binary already matches.
func writeAayu(b *strings.Builder, t Tool) {
	if t.Via == "source" {
		fmt.Fprintf(b, `step "aayu from this checkout" # %s
AAYU_DIR="$HOME/.local/bin"
mkdir -p "$AAYU_DIR"
# A binary built from this commit, with no local changes, is current.
if [ "$(go version -m "$AAYU_DIR/aayudha" 2> /dev/null | awk '$2 ~ /^vcs\.(revision|modified)=/ {print $2}' | xargs)" != "vcs.revision=$(git rev-parse HEAD) vcs.modified=false" ]; then
  CGO_ENABLED=0 go build -trimpath -o "$AAYU_DIR/aayudha" ./cmd/aayudha
fi
`, t.Evidence)
	} else {
		fmt.Fprintf(b, `AAYU_VERSION=%s # %s
step "aayu $AAYU_VERSION"
AAYU_DIR="$HOME/.local/bin"
if [ "$("$AAYU_DIR/aayudha" version 2> /dev/null)" != "aayu $AAYU_VERSION" ]; then
  %sfetch "%s$AAYU_VERSION/aayudha_${AAYU_VERSION}_linux_$ARCH.tar.gz" "$sum" "$tmp/aayu.tar.gz"
  tar -C "$tmp" -xzf "$tmp/aayu.tar.gz" aayudha
  mkdir -p "$AAYU_DIR" && install -m 0755 "$tmp/aayudha" "$AAYU_DIR/aayudha"
fi
`, t.Version, t.Evidence, archCase(t, nil, "  "), aayuReleases)
		if t.Path != "" {
			fmt.Fprintf(b, `# The committed Amp plugin calls aayu by this path, and only when it reports $AAYU_VERSION.
plugin_aayu=%s
[ "$("$plugin_aayu" version 2> /dev/null)" = "aayu $AAYU_VERSION" ] || { as_root mkdir -p "$(dirname "$plugin_aayu")" && as_root ln -sf "$AAYU_DIR/aayudha" "$plugin_aayu"; }
`, shellQuote(t.Path))
		}
	}
	b.WriteString("ln -sf aayudha \"$AAYU_DIR/aayu\"\npath_first \"$AAYU_DIR\"\naayu version\n\n")
}

// shellQuote quotes s as one literal shell word, so a step's label never
// expands what the step itself runs.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func rangesArgs(t Tool) string {
	var qs []string
	for _, r := range t.Accept {
		qs = append(qs, fmt.Sprintf("%q", r))
	}
	return strings.Join(qs, " ")
}

func writeNode(b *strings.Builder, t Tool) {
	fmt.Fprintf(b, `NODE_VERSION=%s # %s
node_ok() { command -v node > /dev/null 2>&1 && in_ranges "$(node --version | sed 's/^v//')" %s; }
step "Node.js (accepts %s; installs $NODE_VERSION when none fits)"
if ! node_ok; then
  %sfetch "https://nodejs.org/dist/v$NODE_VERSION/node-v$NODE_VERSION-linux-$name.tar.xz" "$sum" "$tmp/node.tar.xz"
  as_root tar -C /usr/local --strip-components=1 --no-same-owner -xJf "$tmp/node.tar.xz" --exclude='*.md' --exclude=LICENSE
  hash -r
  node_ok || path_first /usr/local/bin
fi
node --version

`, t.Version, t.Evidence, rangesArgs(t), t.Want, archCase(t, map[string]string{"amd64": "x64", "arm64": "arm64"}, "  "))
}

func writeCorepack(b *strings.Builder, cp, pm Tool) {
	check := fmt.Sprintf(`[ "$(%s --version 2> /dev/null)" = %q ]`, pm.Name, pm.Version)
	if pm.Version == "" {
		check = fmt.Sprintf("command -v %s > /dev/null 2>&1", pm.Name)
	}
	fmt.Fprintf(b, `step "%s %s through corepack" # %s
persist COREPACK_ENABLE_DOWNLOAD_PROMPT=0
if ! %s; then
  if ! command -v corepack > /dev/null 2>&1 || ! version_ge "$(corepack --version)" %q; then
    if [ -w "$(npm prefix -g)/lib" ]; then npm install -g --no-fund --no-audit "corepack@%s"; else as_root npm install -g --no-fund --no-audit "corepack@%s"; fi
    hash -r
  fi
  cpdir=$(dirname "$(command -v corepack)")
  if [ -w "$cpdir" ]; then corepack enable %s; else as_root corepack enable %s; fi
  hash -r
fi
%s --version

`, pm.Name, orStr(pm.Version, "(corepack's default)"), pm.Evidence, check, cp.Version, cp.Version, cp.Version, pm.Name, pm.Name, pm.Name)
}

func writeUV(b *strings.Builder, t Tool) {
	fmt.Fprintf(b, `UV_VERSION=%s # %s
step "uv $UV_VERSION"
if [ "$(/usr/local/bin/uv --version 2> /dev/null | awk '{print $2}')" != "$UV_VERSION" ]; then
  %sfetch "https://github.com/astral-sh/uv/releases/download/$UV_VERSION/uv-$name.tar.gz" "$sum" "$tmp/uv.tar.gz"
  tar -C "$tmp" -xzf "$tmp/uv.tar.gz"
  as_root install -m 0755 "$tmp/uv-$name/uv" "$tmp/uv-$name/uvx" /usr/local/bin/
fi
hash -r
# Another uv earlier on PATH (codex-universal has one in ~/.local/bin) must not win.
[ "$(uv --version 2> /dev/null | awk '{print $2}')" = "$UV_VERSION" ] || path_first /usr/local/bin
uv --version

`, t.Version, t.Evidence, archCase(t, uvTriple, "  "))
}

func writeRust(b *strings.Builder, t Tool) {
	fmt.Fprintf(b, `RUSTUP_VERSION=%s
RUST_TOOLCHAIN=%s # %s
step "Rust $RUST_TOOLCHAIN (rustup $RUSTUP_VERSION)"
if ! command -v rustup > /dev/null 2>&1 && [ ! -x "$HOME/.cargo/bin/rustup" ]; then
  %sfetch "https://static.rust-lang.org/rustup/archive/$RUSTUP_VERSION/$name/rustup-init" "$sum" "$tmp/rustup-init"
  chmod +x "$tmp/rustup-init"
  "$tmp/rustup-init" -y -q --no-modify-path --profile minimal --default-toolchain none
fi
[ -x "$HOME/.cargo/bin/rustup" ] && path_first "$HOME/.cargo/bin"
rustup toolchain install "$RUST_TOOLCHAIN" --profile minimal
[ -f rust-toolchain.toml ] || [ -f rust-toolchain ] || rustup default "$RUST_TOOLCHAIN"
rustc --version

`, t.Version, t.Want, t.Evidence, archCase(t, uvTriple, "  "))
}

var servicePackages = map[string][]string{"postgres": {"postgresql"}, "redis": {"redis-server"}, "mysql": {"mariadb-server"}}

func sqlQuote(s string) string { return strings.ReplaceAll(s, "'", "''") }

func writeServiceSetup(b *strings.Builder, sv Service) {
	switch sv.Name {
	case "postgres":
		b.WriteString(`step "PostgreSQL (` + sv.Evidence + `)"
as_postgres() { if [ "$(id -u)" -eq 0 ]; then runuser -u postgres -- "$@"; else sudo -n -u postgres "$@"; fi; }
for conf in /etc/postgresql/*/main; do # an agent's database: speed over durability
  [ -f "$conf/conf.d/aayu.conf" ] || printf 'fsync = off\nsynchronous_commit = off\nfull_page_writes = off\n' | as_root tee "$conf/conf.d/aayu.conf" > /dev/null
done
`)
		if sv.User != "" {
			db := orStr(sv.Database, sv.User)
			fmt.Fprintf(b, `as_root service postgresql start > /dev/null
for _ in $(seq 30); do pg_isready -q && break; sleep 1; done
as_postgres psql -tAc "SELECT 1 FROM pg_roles WHERE rolname = '%s'" | grep -q 1 ||
  as_postgres psql -q -v ON_ERROR_STOP=1 -c "CREATE ROLE \"%s\" LOGIN SUPERUSER"
as_postgres psql -q -v ON_ERROR_STOP=1 -c "ALTER ROLE \"%s\" LOGIN PASSWORD '%s'" # also when the role exists (postgres)
as_postgres psql -tAc "SELECT 1 FROM pg_database WHERE datname = '%s'" | grep -q 1 || as_postgres createdb -O "%s" "%s"
as_root service postgresql stop > /dev/null
`, sqlQuote(sv.User), sv.User, sv.User, sqlQuote(sv.Password), sqlQuote(db), sv.User, db)
		}
		b.WriteString("\n")
	case "mysql":
		fmt.Fprintf(b, "step \"MariaDB (%s)\"\n", sv.Evidence)
		if sv.User != "" {
			db := orStr(sv.Database, sv.User)
			fmt.Fprintf(b, `as_root service mariadb start > /dev/null
as_root mariadb -e "CREATE DATABASE IF NOT EXISTS `+"`%s`"+`; CREATE USER IF NOT EXISTS '%s'@'localhost' IDENTIFIED BY '%s'; GRANT ALL ON *.* TO '%s'@'localhost'"
as_root service mariadb stop > /dev/null
`, db, sqlQuote(sv.User), sqlQuote(sv.Password), sqlQuote(sv.User))
		}
		b.WriteString("\n")
	}
}

func startScript(s Spec, fp string) string {
	var b strings.Builder
	b.WriteString(header("Starts the services the tests need. Hosts run it per session: Amp from .agents/resume, Cursor as start,\n# Claude Code from its SessionStart hook, Codex from its Start skill; .agents/check runs it too.", fp))
	b.WriteString(prelude)
	b.WriteString(loadDotenv(s))
	b.WriteString("wait_for() { local i; for i in $(seq 30); do \"$@\" > /dev/null 2>&1 && return 0; sleep 1; done; echo \"aayu-env: $* never answered\" >&2; return 1; }\n\n")
	names := map[string]bool{}
	for _, sv := range s.Services {
		names[sv.Name] = true
	}
	var order []string
	for n := range names {
		order = append(order, n)
	}
	sort.Strings(order)
	for _, n := range order {
		switch n {
		case "postgres":
			b.WriteString("step \"PostgreSQL\"\npg_isready -q 2> /dev/null || as_root service postgresql start > /dev/null\nwait_for pg_isready -q\n\n")
		case "redis":
			b.WriteString("step \"Redis\"\nredis-cli ping > /dev/null 2>&1 || as_root service redis-server start > /dev/null\nwait_for redis-cli ping\n\n")
		case "mysql":
			b.WriteString("step \"MariaDB\"\nas_root mariadb-admin ping > /dev/null 2>&1 || as_root service mariadb start > /dev/null\nwait_for as_root mariadb-admin ping\n\n")
		}
	}
	b.WriteString("echo \"aayu-env: services ready\"\n")
	return b.String()
}

func resumeScript(fp string) string {
	return header("Amp runs this after an orb starts and each time it wakes: the services setup installed come back up.", fp) + StartCommand + "\n"
}

// Marker is the check script's last line on success; a cloud probe's reply
// must carry it with the expected fingerprint.
const Marker = "aayu-env ok"

func checkScript(s Spec, fp string) string {
	var b strings.Builder
	b.WriteString(header("Proves an agent can work here: the pinned toolchains are the ones on PATH, services start, and the\n# build and tests pass. Its last line is the marker a cloud probe replies with.", fp))
	b.WriteString(prelude)
	b.WriteString(loadDotenv(s))
	b.WriteString("expect() { [ \"$2\" = \"$3\" ] || { echo \"aayu-env: $1 is '$2', want '$3' (PATH=$PATH)\" >&2; exit 1; }; }\n\n")
	for _, t := range s.Tools {
		switch t.Name {
		case "go":
			fmt.Fprintf(&b, "expect go \"$(GOTOOLCHAIN=local go env GOVERSION)\" go%s\n", t.Version)
		case "node":
			fmt.Fprintf(&b, "in_ranges \"$(node --version | sed 's/^v//')\" %s || { echo \"aayu-env: node $(node --version) is outside %s\" >&2; exit 1; }\n", rangesArgs(t), t.Want)
		case "pnpm", "yarn":
			if t.Version != "" {
				fmt.Fprintf(&b, "expect %s \"$(%s --version)\" %s\n", t.Name, t.Name, t.Version)
			}
		case "uv":
			fmt.Fprintf(&b, "expect uv \"$(uv --version | awk '{print $2}')\" %s\n", t.Version)
		case "rust":
			b.WriteString("rustc --version\n")
		case "aayu":
			if t.Via == "release" {
				fmt.Fprintf(&b, "expect aayu \"$(aayu version)\" \"aayu %s\"\n", t.Version)
			} else {
				b.WriteString("aayu version\n")
			}
		}
	}
	b.WriteString(gateScript(s))
	if len(s.Services) > 0 {
		b.WriteString(StartCommand + "\n")
	}
	for _, c := range s.Checks {
		fmt.Fprintf(&b, "step %s\n%s\n", shellQuote(c.Run), c.Run)
	}
	fmt.Fprintf(&b, "echo %q\n", Marker+" "+fp)
	return b.String()
}
